// LLM이 표의 숫자를 순서대로 채우면 빈 칸에서 값이 밀린다.
// 이름이 표의 한 행과 맞는 약은 좌표로 맞춘 표 값(빈 칸은 null)으로 덮어쓴다.
function normalizeName(name) {
  return String(name || '').replace(/[\s·…]|\.{2,}/g, '').toLowerCase();
}

function sameMedicine(a, b) {
  const x = normalizeName(a), y = normalizeName(b);
  if (!x || !y) return false;
  return x === y || (Math.min(x.length, y.length) >= 3 && (x.startsWith(y) || y.startsWith(x)));
}

function unitOf(dosagePerTake, medicineName) {
  const unit = String(dosagePerTake || '').replace(/[\d./½\s]/g, '');
  if (unit) return unit;
  if (/캡슐/.test(medicineName)) return '캡슐';
  if (/과립|산|시럽|현탁/.test(medicineName)) return '포';
  return '정';
}

function toInteger(value) {
  if (value === null || value === undefined) return null;
  const n = Number(value);
  return Number.isInteger(n) && n > 0 ? n : null;
}

/** 이름이 표의 한 행과 맞는 약은 세 값을 표 값으로 바꾼다. 표에서 비어 있던 칸은 null로 둔다. */
function applyTableRows(prescriptions, rows) {
  if (!Array.isArray(prescriptions) || !rows?.length) return prescriptions;
  const used = new Set();
  const numberIn = text => (String(text ?? '').match(/\d+(?:\.\d+)?/) || [null])[0];
  // 같은 이름이 여러 행에 있으면(본표와 영수증 목록 등) LLM 값과 가장 많이 일치하는 행을 고른다.
  const agreement = (p, row) =>
    (numberIn(p.dosagePerTake) === row.dosage ? 1 : 0) +
    (String(p.dailyFrequency ?? '') === String(row.frequency ?? '') ? 1 : 0) +
    (String(p.durationDays ?? '') === String(row.days ?? '') ? 1 : 0);
  return prescriptions.map(p => {
    let index = -1;
    rows.forEach((row, i) => {
      if (used.has(i) || !sameMedicine(p.medicineName, row.name)) return;
      if (index < 0 || agreement(p, row) > agreement(p, rows[index])) index = i;
    });
    if (index < 0) return p;
    used.add(index);
    const row = rows[index];
    return {
      ...p,
      dosagePerTake: row.dosage === null ? null : `${row.dosage}${unitOf(p.dosagePerTake, p.medicineName)}`,
      dailyFrequency: toInteger(row.frequency),
      durationDays: toInteger(row.days),
    };
  });
}

const rows = $('Code in JavaScript').first().json.table_rows || [];
return $input.all().map(item => {
  const output = item.json.output || {};
  try {
    return { json: { ...item.json, output: { ...output, prescriptions: applyTableRows(output.prescriptions || [], rows) } } };
  } catch (e) {
    // 적용에 실패하면 LLM 결과를 그대로 넘긴다.
    return item;
  }
});

