parameters.jsCode:
// 표 형식 복약 안내서에서 숫자를 헤더 열 위치에 맞춰 약품별로 묶는다.
// LLM이 "한 줄의 숫자를 앞에서부터 순서대로" 채우면 빈 칸이 있을 때 값이 한 칸씩 밀리기 때문에,
// 열 배정은 좌표로 정하고 LLM에는 참고값으로 넘긴다.

const COLUMN_KEYWORDS = {
  dosage: /투약량|투여량|복용량|1회량/,
  frequency: /횟수/,
  days: /일수/,
};
const HEADER_PREFIX = /^(1회|1일|하루|총)$/;
const NUMBER_TOKEN = /^(\d+(?:\.\d+)?|\d+\/\d+|½)(정|캡슐|포|회|일|T|C)?$/;

function box(word) {
  const xs = (word.boundingBox?.vertices || []).map(v => v.x ?? 0);
  const ys = (word.boundingBox?.vertices || []).map(v => v.y ?? 0);
  const x1 = Math.min(...xs), x2 = Math.max(...xs), y1 = Math.min(...ys), y2 = Math.max(...ys);
  return { text: String(word.text || '').trim(), x1, x2, y1, y2, cx: (x1 + x2) / 2, cy: (y1 + y2) / 2, h: y2 - y1 };
}

function median(values) {
  const sorted = [...values].sort((a, b) => a - b);
  return sorted.length ? sorted[Math.floor(sorted.length / 2)] : 0;
}

function toNumberText(text) {
  const match = text.match(NUMBER_TOKEN);
  if (!match) return null;
  const raw = match[1];
  if (raw === '½') return '0.5';
  if (raw.includes('/')) {
    const [a, b] = raw.split('/').map(Number);
    return b ? String(Math.round((a / b) * 100) / 100) : null;
  }
  return raw;
}

/** 같은 줄에서 키워드 앞의 "1회", "총" 같은 접두어를 열 범위에 합친다. */
function columnSpan(keywordWord, sameLine, lineHeight) {
  let x1 = keywordWord.x1;
  const prefix = sameLine
    .filter(w => w.x2 <= keywordWord.x1 && keywordWord.x1 - w.x2 < lineHeight * 1.2 && HEADER_PREFIX.test(w.text))
    .sort((a, b) => b.x2 - a.x2)[0];
  if (prefix) x1 = prefix.x1;
  return { x1, x2: keywordWord.x2, cx: (x1 + keywordWord.x2) / 2, y: keywordWord.cy };
}

/** 투약량·횟수·일수 세 열이 왼쪽부터 순서대로 있는 헤더를 모두 찾는다. */
function findHeaders(words, lineHeight) {
  const headers = [];
  const dosageWords = words.filter(w => COLUMN_KEYWORDS.dosage.test(w.text));
  for (const dosage of dosageWords) {
    const sameLine = words.filter(w => Math.abs(w.cy - dosage.cy) < lineHeight * 0.8);
    const frequency = sameLine
      .filter(w => w !== dosage && COLUMN_KEYWORDS.frequency.test(w.text) && w.x1 > dosage.x2)
      .sort((a, b) => a.x1 - b.x1)[0];
    if (!frequency) continue;
    const days = sameLine
      .filter(w => w !== frequency && COLUMN_KEYWORDS.days.test(w.text) && w.x1 > frequency.x2)
      .sort((a, b) => a.x1 - b.x1)[0];
    if (!days) continue;
    // 한 단어에 세 키워드가 다 들어 있는 "복약안내(투약량/횟수/일수)" 같은 제목은 열이 아니다.
    if (dosage === frequency || frequency === days) continue;
    const nameHeader = sameLine
      .filter(w => /약품명|약명|품명/.test(w.text) && w.x2 < dosage.x1)
      .sort((a, b) => b.x2 - a.x2)[0];
    headers.push({
      y: dosage.cy,
      y2: Math.max(dosage.y2, frequency.y2, days.y2),
      name: nameHeader ? { x1: nameHeader.x1, x2: nameHeader.x2 } : null,
      columns: {
        dosage: columnSpan(dosage, sameLine, lineHeight),
        frequency: columnSpan(frequency, sameLine, lineHeight),
        days: columnSpan(days, sameLine, lineHeight),
      },
    });
  }
  return headers.sort((a, b) => a.y - b.y);
}

const COLUMN_KEYS = ['dosage', 'frequency', 'days'];

/** 숫자의 가로 중심을 가장 가까운 열 중심에 배정한다. */
function nearestColumn(cx, centers) {
  return COLUMN_KEYS.reduce((best, key) =>
    Math.abs(cx - centers[key]) < Math.abs(cx - centers[best]) ? key : best, COLUMN_KEYS[0]);
}

/** 세로 위치가 가까운 숫자끼리 한 행으로 묶는다. */
function groupByLine(numbers, lineHeight) {
  const groups = [];
  for (const number of [...numbers].sort((a, b) => a.cy - b.cy)) {
    const group = groups.find(g => Math.abs(g.cy - number.cy) < lineHeight * 0.6);
    if (group) {
      group.items.push(number);
      group.cy = group.items.reduce((sum, n) => sum + n.cy, 0) / group.items.length;
    } else {
      groups.push({ cy: number.cy, items: [number] });
    }
  }
  groups.forEach(g => g.items.sort((a, b) => a.cx - b.cx));
  return groups;
}

function isNameWord(word) {
  return toNumberText(word.text) === null && /^[가-힣A-Za-z]/.test(word.text) && !/[\[\]()]/.test(word.text);
}

function extractTableRows(page) {
  const words = (page?.words || []).map(box).filter(w => w.text);
  if (!words.length) return [];
  const lineHeight = median(words.map(w => w.h)) || 20;
  const pageWidth = page.width || Math.max(...words.map(w => w.x2));
  const headers = findHeaders(words, lineHeight);
  const rows = [];

  headers.forEach((header, index) => {
    const tableLeft = (header.name?.x1 ?? header.columns.dosage.x1 - pageWidth * 0.4) - lineHeight * 6;
    // 오른쪽에 다른 표가 있으면 그 표의 시작 전까지만 이 표로 본다.
    const neighbor = headers
      .filter(h => h !== header && (h.name?.x1 ?? h.columns.dosage.x1) > header.columns.days.x2)
      .map(h => (h.name?.x1 ?? h.columns.dosage.x1) - lineHeight * 6)
      .sort((a, b) => a - b)[0];
    const tableRight = neighbor ?? pageWidth;
    const next = headers.slice(index + 1)
      .find(h => h.columns.dosage.x1 < tableRight && h.columns.days.x2 > tableLeft);
    const bottom = next ? next.y - lineHeight * 0.5 : Infinity;
    const nameRight = header.name ? header.name.x2 + lineHeight * 2 : header.columns.dosage.x1;

    const numbers = words
      .filter(w => w.cy > header.y2 + lineHeight * 0.3 && w.cy < bottom && w.x1 > nameRight && w.x2 <= tableRight)
      .map(w => ({ ...w, value: toNumberText(w.text) }))
      .filter(w => w.value !== null);
    const groups = groupByLine(numbers, lineHeight).filter(g => g.items.length <= 3);

    // 세 칸이 모두 찬 행은 순서가 곧 열이다. 이 행들로 실제 숫자 열의 위치를 구한다.
    // 헤더 글자는 가운데 정렬 등으로 숫자 열과 어긋날 수 있어, 모두 찬 행이 없을 때만 헤더 위치를 쓴다.
    const complete = groups.filter(g => g.items.length === 3);
    const centers = {};
    COLUMN_KEYS.forEach((key, i) => {
      centers[key] = complete.length ? median(complete.map(g => g.items[i].cx)) : header.columns[key].cx;
    });

    const inTable = words.filter(w =>
      w.cy > header.y2 && w.cy < bottom && w.x1 >= tableLeft && w.x2 < centers.dosage && isNameWord(w));
    // 약품명은 약품명 열 안에서 시작한다. 그 오른쪽의 복약 안내 문구는 이름이 아니다.
    const nameColumnRight = header.name
      ? header.name.x2
      : Math.min(...inTable.map(w => w.x1)) + lineHeight * 3;
    const nameCandidates = inTable.filter(w => w.x1 <= nameColumnRight);
    // 같은 열에서도 약품명은 한 왼쪽 선에 맞춰 적혀 있다.
    const nameX = Math.min(...nameCandidates.map(w => w.x1));

    const columnGap = Math.min(centers.frequency - centers.dosage, centers.days - centers.frequency);
    const numberAreaLeft = centers.dosage - columnGap / 2;
    const numberAreaRight = centers.days + columnGap / 2;

    for (const group of groups) {
      // 숫자 열 안에 "이하" 같은 글자가 함께 있으면 표의 행이 아니다(예: "이하 5정" 생략 표시).
      const mixedText = words.some(w =>
        Math.abs(w.cy - group.cy) < lineHeight * 0.6 && w.cx > numberAreaLeft && w.cx < numberAreaRight &&
        toNumberText(w.text) === null);
      if (mixedText) continue;
      const cells = { dosage: null, frequency: null, days: null };
      if (group.items.length === 3) {
        COLUMN_KEYS.forEach((key, i) => { cells[key] = group.items[i].value; });
      } else {
        const keys = group.items.map(n => nearestColumn(n.cx, centers));
        if (new Set(keys).size !== keys.length) continue; // 두 숫자가 같은 열로 가면 판단하지 않는다
        group.items.forEach((n, i) => { cells[keys[i]] = n.value; });
      }
      const name = nameCandidates
        .filter(w => Math.abs(w.cy - group.cy) < lineHeight * 1.5 && Math.abs(w.x1 - nameX) < lineHeight * 2)
        .sort((a, b) => Math.abs(a.cy - group.cy) - Math.abs(b.cy - group.cy))[0];
      if (!name) continue;
      rows.push({ name: name.text, ...cells });
    }
  });
  return rows;
}

const ocrResponse = $input.all()[0].json;
const firstPage = ocrResponse.pages?.[0] || {};
const pageWords = firstPage.words || [];

const formattedWords = pageWords.map(word => {
  return {
    text: word.text,
    coordinates: word.boundingBox?.vertices || []
  };
});

let jobId = "JOB_ID_NOT_FOUND";

try {
  const webhookData = $('Webhook').item.json;
  jobId = webhookData.query?.jobId || "JOB_ID_NOT_FOUND";
} catch (e) {
  try {
    const webhookAll = $('Webhook').all();
    jobId = webhookAll[0]?.json?.query?.jobId || "JOB_ID_NOT_FOUND";
  } catch (err) {
    jobId = "JOB_ID_NOT_FOUND";
  }
}

// 표의 숫자를 좌표로 열에 맞춘 결과. 실패해도 OCR 결과만으로 LLM이 처리하도록 빈 목록을 넘긴다.
let tableRows = [];
try {
  tableRows = extractTableRows(firstPage);
} catch (e) {
  tableRows = [];
}

return [{
  json: {
    jobId: jobId,
    extracted_text: firstPage.text || ocrResponse.text || "",
    words_with_coordinates: formattedWords,
    table_rows: tableRows
  }
}];

